// Fonts for the generated share cards (Anton for headlines, Oswald for the
// small caps). They are embedded as base64 so the /api/og function never has
// to find font files on disk once it is deployed. Both families are SIL OFL
// licensed (via the @fontsource packages). Regenerate only if the type changes.
const anton400 = ""
const oswald500 = ""
const oswald600 = ""
const oswald700 = ""

function toArrayBuffer(b64: string): ArrayBuffer {
	const buf = Buffer.from(b64, "base64")
	return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer
}

export type OgFont = { name: string; data: ArrayBuffer; weight: 400 | 500 | 600 | 700; style: "normal" }

let cached: OgFont[] | null = null

export function ogFonts(): OgFont[] {
	if (!cached) {
		cached = [
			{ name: "Anton", data: toArrayBuffer(anton400), weight: 400, style: "normal" },
			{ name: "Oswald", data: toArrayBuffer(oswald500), weight: 500, style: "normal" },
			{ name: "Oswald", data: toArrayBuffer(oswald600), weight: 600, style: "normal" },
			{ name: "Oswald", data: toArrayBuffer(oswald700), weight: 700, style: "normal" },
		]
	}
	return cached
}
